+        row.update(host_meta=meta, source=meta["source"], host_prepare_wall_ms=prepare_ms)
+        row["mode"] = meta["mode"]
+        row["python_build_ms"] = meta["build_ms"]
+        row["python_peak_rss_bytes"] = poller.stop()
